90	// TestEnable_ExternalBackend_HuskyShape_EndToEnd is the end-to-end tracer for
91	// the external git hooks backend. It exercises the full `entire enable` path
92	// in a Husky-shaped repository (.husky/_/* stubs + .husky/<hook> user scripts)
93	// and asserts:
94	//  1. exit code 0
95	//  2. stdout contains the variant-3 hint line
96	//  3. .git/hooks/ is byte-identical before and after (no install)
97	//  4. .husky/ is byte-identical before and after (no writes to user dir)
98	//
99	// This test is the safety net for the design contract: external mode must
100	// be detection-only. If any cycle's GREEN implementation accidentally writes
101	// to .git/hooks/ or .husky/, this test catches it.
102	func TestEnable_ExternalBackend_HuskyShape_EndToEnd(t *testing.T) {
103		t.Parallel()
104		env := NewRepoWithCommit(t)
105	
106		// Husky shape: stubs in .husky/_/, user scripts in .husky/<hook>.
107		// Each user script carries the Entire marker and a dispatch call so
108		// IsGitHookInstalled detects them.
109		huskyDir := filepath.Join(env.RepoDir, ".husky")
110		huskyStubsDir := filepath.Join(huskyDir, "_")
111		if err := os.MkdirAll(huskyStubsDir, 0o755); err != nil {
112			t.Fatal(err)
113		}
114	
115		managedHooks := []string{"prepare-commit-msg", "commit-msg", "post-commit", "post-rewrite", "pre-push"}
116		for _, h := range managedHooks {
